HARD_REFERENCES = {t["id"]: t["reference"] for t in HARD_TASKS}

def validate_hard(tasks=None, verbose=True):
    """Validate the hard task bank."""
    if tasks is None:
        tasks = HARD_TASKS
    import tempfile, sys, os
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    from probe import test_function_code
    all_ok = True
    for task in tasks:
        ref = HARD_REFERENCES.get(task["id"])
        if ref is None:
            if verbose:
                print(f"  {task['id']:<28} SKIP (no reference)")
            continue
        with tempfile.TemporaryDirectory() as td:
            passed, total, failures = test_function_code(ref, task, td)
        ok = (passed == total)
        if not ok:
            all_ok = False
        if verbose:
            status = "OK" if ok else f"FAIL ({passed}/{total})"
            print(f"  {task['id']:<28} {status}")
    return all_ok
